      return {
        ...user,
        encryptedField: decryptUserData(user.encryptedField)
      };
    });

    // Output the decrypted user data to a file
    fs.writeFileSync('decrypted_users.json', JSON.stringify(decryptedUsers, null, 2));
    console.log('Decrypted user data saved to decrypted_users.json');
  } catch (error) {
    console.error('Error during audit process:', error);
  }
}

main();
```

